// One item per target: the HTTP node below then runs once per item, which is
// what lets a single failure stay contained instead of ending the run.
return [
  { json: { name: 'Public site', url: 'https://example.com/' } },
  { json: { name: 'API health', url: 'https://example.com/api/health' } },
  { json: { name: 'Docs', url: 'https://example.com/docs' } },
];

// Judge every target, then decide once. Anything 2xx/3xx passes.
const targets = $('[H1] Targets').all().map(i => i.json);
const probes = $input.all();

const results = probes.map((p, i) => {
  const status = Number(p.json?.statusCode ?? 0);
  const ok = status >= 200 && status < 400;
  return {
    name: targets[i]?.name ?? `target ${i + 1}`,
    url: targets[i]?.url ?? '',
    status: status || 'no response',
    ok,
  };
});

const failed = results.filter(r => !r.ok);

return [{ json: {
  checkedAt: new Date().toISOString(),
  total: results.length,
  failedCount: failed.length,
  anyDown: failed.length > 0,
  results,
  // Plain text, because the value of an alert is being readable on a phone.
  digest: failed.map(f => `DOWN  ${f.name}  (${f.status})  ${f.url}`).join('\n'),
} }];
